#!/usr/bin/env python3
"""FS3 v199 - the capital ships with a model carry their real armament.

    Turrets    Silvio: every turret of the model, with the weapon the ship
               table gives it, in place of the mounts set by hand. Number
               and weapons as in FreeSpace (the Sathanas 13 beams, 22 guns,
               13 flak, 5 launchers). Values in FreeSpace's proportion,
               measured against a weapon the game already had for each
               kind: Terran Turret (guns), BGreen and AAAf on the Orion
               (beams), Standard Flak (flak), Piranha (launchers). Ships
               without a beam in FreeSpace have none now (Fenris,
               Charybdis). The Lucifer's reactors stay where they were.
    Engines    The engine flames come from the model's engine glows.
    Hits       A ship drawn from her model is hit where her model is: the
               hit map is her side view instead of the sprite's outline.
    M69        A protected ship in her death roll counts as lost at once:
               the jump clock running out during the roll no longer calls
               the Hecate 'jumped out'.

Needs v198. Edits src/30_waves.js, 40_world.js, 50_combat.js,
57_turrets.js, 59_field3d.js, 60_effects.js, fieldsim.js and wpnsim.js.
Run assemble.py afterwards.
"""
import base64
import os
import sys

if not os.path.exists("src/59_field3d.js"):
    sys.exit("Abbruch: erst v198 einspielen.")
_f = open("src/59_field3d.js", encoding="utf-8").read()
if "F3D_GUNS" in _f:
    sys.exit("Abbruch: v199 ist schon eingespielt.")
if "F3D_TUR" not in _f:
    sys.exit("Abbruch: erst v198 einspielen.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)
